from __future__ import annotations

import json

import pytest
from pydantic import RootModel

from llm_router import LLMRouter, Model, Provider, RouterProfile
from tests.llm_router.support.fault_server import ScriptedHTTPServer, ScriptedResponse
from tests.llm_router.support.workers.retry import (
    openai_chat_path,
    openai_success_response,
)
from tests.llm_router.support.workers.worker_patches import patched_openai_sdk

pytestmark = pytest.mark.verification_kind("unit")

_CHAT_PATH = openai_chat_path()

_EMPTY_FENCED_BODY = "```\n```"


class EmptyPayload(RootModel[str]):
    """Empty string payload result."""


def _fenced_route() -> LLMRouter:
    return LLMRouter(
        RouterProfile(model=Model.DEEPSEEK_V3, provider=Provider.OPENROUTER),
        temperature=0.0,
    )


def _query_with_body(monkeypatch: pytest.MonkeyPatch, body_text: str):
    monkeypatch.setenv("OPENROUTER_API_KEY_1", "fence-assurance-value")
    response_body = openai_success_response(text=body_text)
    with (
        ScriptedHTTPServer(
            port=0,
            routes={
                ("POST", _CHAT_PATH): [
                    ScriptedResponse(
                        status_code=200,
                        headers={"Content-Type": "application/json"},
                        body=response_body,
                    )
                ]
            },
        ) as server,
        patched_openai_sdk(
            forced_base_url=f"{server.base_url}/v1",
            disable_sdk_retries=True,
        ),
    ):
        return _fenced_route().query(
            "Extract the payload value. Use the requested schema.",
            response_schema=EmptyPayload,
        )


@pytest.mark.verifies("REQ_STRUCTURED_TEXT_OUTPUT[revision==2]")
def test_empty_fence_unwraps_to_empty_payload(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """An empty fenced payload is stripped fully before validation."""
    with pytest.raises(
        Exception, match=r"Structured output validation failed"
    ) as exc_info:
        _query_with_body(monkeypatch, _EMPTY_FENCED_BODY)

    cause = exc_info.value.cause
    if isinstance(cause, json.JSONDecodeError):
        parsed_text = cause.doc
    else:
        parsed_text = next(iter(cause.errors()))["input"]

    assert parsed_text == ""
